import { useEffect, useMemo, useState } from 'react'
import { approveDispatchPlan, assertNetworkInvariants, closeShelterAndRevalidate, expireReservation, generateDispatchPlan, runScenario as executeScenario, transitionShipment, validateAllocation } from './engine.js'
import { hydrateState, seedState } from './data.js'

const NAV = [
  ['overview', 'Operations overview', 'grid'],
  ['donations', 'Donations', 'box'],
  ['shelters', 'Shelters', 'home'],
  ['riders', 'Riders', 'users'],
  ['dispatch', 'Dispatch center', 'route'],
  ['shipments', 'Live shipments', 'truck'],
  ['exceptions', 'Exceptions', 'alert'],
  ['simulation', 'Simulation lab', 'flask'],
  ['audit', 'Audit & impact', 'pulse'],
]

const SCENARIOS = [
  { id: 'oversized', letter: 'A', title: 'Oversized donation', detail: 'Split 180 meals across riders and shelters without violating capacity or demand.', expected: 'Capacity-compliant shipments and residual explanation.' },
  { id: 'ghost', letter: 'B', title: 'Ghost reservation', detail: 'Expire an unacknowledged reservation and release quantity exactly once.', expected: 'Atomic release, reassignment, stale response rejected.' },
  { id: 'closure', letter: 'C', title: 'Shelter closes in transit', detail: 'Close a destination while custody is preserved and find a safe fallback.', expected: 'Reroute proposal or RECOVERY_REQUIRED.' },
  { id: 'dependency', letter: 'D', title: 'Dependency mismatch', detail: 'Check required water and fuel resources for ration kits.', expected: 'Incompatible shelter blocked with reason.' },
  { id: 'deadline', letter: 'E', title: 'Safety deadline breach', detail: 'Try to dispatch when every route exceeds the safe window.', expected: 'All routes blocked; no override.' },
  { id: 'claims', letter: 'F', title: 'Simultaneous claims', detail: 'Two riders compete for the last 20 meals.', expected: 'One reservation succeeds; balance never goes negative.' },
  { id: 'rider-failure', letter: 'G', title: 'Rider failure after pickup', detail: 'Preserve custody and require validated handoff options.', expected: 'Exception raised with custody preserved.' },
  { id: 'no-fallback', letter: 'H', title: 'No fallback destination', detail: 'Close the destination when every alternative is unsafe or full.', expected: 'RECOVERY_REQUIRED; no fabricated delivery.' },
]

function Icon({ name, size = 18 }) {
  const paths = {
    grid: 'M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z',
    box: 'M4 7.5 12 3l8 4.5v9L12 21l-8-4.5v-9ZM12 21V12m8-4.5-8 4.5-8-4.5M8 5.2l8 4.6',
    home: 'm3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V10Zm6 11v-6h6v6',
    users: 'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m8-10a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm6-3a4 4 0 0 1 0 8m2 5v-2a4 4 0 0 0-3-3.87',
    route: 'M4 19c4-7 12-7 16-14M4 19h5m-5 0v-5m16-9h-5m5 0v5',
    truck: 'M3 6h11v10H3zM14 10h4l3 3v3h-7zM7 19a2 2 0 1 0 0-4 2 2 0 0 0 0 4Zm11 0a2 2 0 1 0 0-4 2 2 0 0 0 0 4Z',
    alert: 'M12 3 2 20h20L12 3Zm0 6v5m0 3h.01',
    flask: 'M9 3h6m-5 0v6l-5.5 9.5A1 1 0 0 0 5.36 20h13.28a1 1 0 0 0 .86-1.5L14 9V3M7 15h10',
    pulse: 'M3 12h4l2-7 4 14 2-7h6',
    settings: 'M12 15.5a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7Zm7.4-3.5a7.5 7.5 0 0 0-.1-1l2-1.5-2-3.4-2.4 1a7.7 7.7 0 0 0-1.7-1L15 3h-4l-.3 3.1a7.7 7.7 0 0 0-1.7 1l-2.4-1-2 3.4 2 1.5a7.5 7.5 0 0 0-.1 1 7.5 7.5 0 0 0 .1 1l-2 1.5 2 3.4 2.4-1a7.7 7.7 0 0 0 1.7 1L11 21h4l.3-3.1a7.7 7.7 0 0 0 1.7-1l2.4 1 2-3.4-2-1.5c.1-.3.1-.7.1-1Z',
    search: 'm20 20-4.5-4.5m2.5-5.5a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',
    bell: 'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9Zm-8 13h4',
    chevron: 'm9 18 6-6-6-6',
    plus: 'M12 5v14M5 12h14',
    play: 'm8 5 11 7-11 7V5Z',
    refresh: 'M20 11a8 8 0 1 0 1 5m-1-9v4h-4',
    check: 'm5 12 4 4L19 6',
    close: 'm6 6 12 12M18 6 6 18',
    download: 'M12 3v12m0 0 4-4m-4 4-4-4M5 21h14',
  }
  return <svg className="icon" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d={paths[name] || paths.grid} /></svg>
}

const fmtTime = (value) => new Date(value).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
const fmtDate = (value) => new Date(value).toLocaleDateString([], { month: 'short', day: 'numeric' })
const minutesLeft = (value) => Math.max(0, Math.round((new Date(value).getTime() - Date.now()) / 60000))

function Badge({ children, tone = 'slate' }) { return <span className={`badge badge-${tone}`}>{children}</span> }
function Button({ children, onClick, variant = 'primary', icon, disabled = false, type = 'button' }) { return <button type={type} className={`button button-${variant}`} disabled={disabled} onClick={onClick}>{icon && <Icon name={icon} size={15} />}{children}</button> }
function SectionHeading({ eyebrow, title, detail, action }) { return <div className="section-heading"><div><div className="eyebrow">{eyebrow}</div><h2>{title}</h2>{detail && <p>{detail}</p>}</div>{action}</div> }
function EmptyState({ title, detail }) { return <div className="empty-state"><div className="empty-mark"><Icon name="grid" size={19} /></div><strong>{title}</strong><span>{detail}</span></div> }

export default function App() {
  const [initialSnapshot] = useState(() => {
    try {
      const hydrated = hydrateState(JSON.parse(localStorage.getItem('resqroute-state')))
      return { state: hydrated.state, notice: hydrated.recovered ? hydrated.reason : null }
    } catch {
      return { state: seedState(), notice: 'Saved demo state could not be read and was replaced with the known-good baseline.' }
    }
  })
  const [hydrationNotice, setHydrationNotice] = useState(initialSnapshot.notice)
  const [state, setState] = useState(initialSnapshot.state)
  const [page, setPage] = useState('overview')
  const [selectedShipment, setSelectedShipment] = useState('SHP-2408')
  const [toast, setToast] = useState(null)
  const [query, setQuery] = useState('')
  const [role, setRole] = useState('Operations administrator')
  const [modal, setModal] = useState(null)

  useEffect(() => localStorage.setItem('resqroute-state', JSON.stringify(state)), [state])
  useEffect(() => { if (!toast) return undefined; const timer = setTimeout(() => setToast(null), 3600); return () => clearTimeout(timer) }, [toast])
  useEffect(() => { if (!hydrationNotice) return; setToast({ message: hydrationNotice, tone: 'error' }); setHydrationNotice(null) }, [hydrationNotice])

  const selected = state.shipments.find((s) => s.id === selectedShipment) || state.shipments[0]
  const metrics = useMemo(() => ({
    activeBatches: state.donations.filter((d) => d.availableQuantity > 0).length,
    inTransit: state.shipments.filter((s) => s.status === 'IN_TRANSIT').length,
    riders: state.riders.filter((r) => r.availability === 'AVAILABLE').length,
    exceptions: state.exceptions.filter((e) => e.status === 'OPEN').length,
    deliveredMeals: state.shipments.filter((s) => s.status === 'DELIVERED' && s.itemType === 'Prepared meals').reduce((sum, s) => sum + s.quantity, 0),
    deliveredAid: state.shipments.filter((s) => s.status === 'DELIVERED' && s.itemType !== 'Prepared meals').reduce((sum, s) => sum + s.quantity, 0),
    awaiting: state.donations.reduce((sum, d) => sum + d.availableQuantity, 0),
    recovered: state.audits.filter((a) => /expired|release/i.test(a.reason)).length,
    reroutes: state.audits.filter((a) => /reroute/i.test(a.reason)).length,
  }), [state])

  function notify(message, tone = 'success') { setToast({ message, tone }) }
  function update(mutator) { setState((current) => ({ ...mutator(current), lastUpdated: new Date().toISOString() })) }
  function reset() { const fresh = seedState(); setState(fresh); notify('Demo baseline restored. All quantities reconciled.', 'success') }

  function expireSelectedReservation(shipmentId) {
    let result
    setState((current) => {
      result = expireReservation(current, shipmentId, new Date())
      if (!result.ok) return current
      const timestamp = new Date().toISOString()
      return { ...result.state, audits: [{ id: `AUD-${Date.now()}`, actor: 'system.reservation-expiry', entity: shipmentId, from: 'RESERVED', to: 'EXPIRED', reason: 'Reservation expired without acknowledgement; quantity released once', result: 'PASS', time: timestamp }, ...current.audits], activity: [{ id: `ACT-${Date.now()}`, title: 'Reservation expired', detail: `${shipmentId} · ${result.shipment.quantity} ${result.shipment.unit} released for reassignment`, tone: 'amber', time: timestamp }, ...current.activity], lastUpdated: timestamp }
    })
    if (!result?.ok) { notify(result?.errors?.join(' · ') || 'Reservation expiry failed.', 'error'); return }
    notify(`${shipmentId} expired and its quantity was released exactly once.`)
  }

  function generatePlan() {
    let generated
    setState((current) => {
      const plan = generateDispatchPlan({ donations: current.donations, shelters: current.shelters, riders: current.riders, now: new Date() })
      generated = plan
      const timestamp = new Date().toISOString()
      return { ...current, plans: plan.plans.map((item, index) => ({ ...item, id: `PLAN-${Date.now()}-${index}`, status: 'PROPOSED' })), residuals: plan.residuals, rejections: plan.rejections, activity: [{ id: `ACT-${Date.now()}`, title: 'Dispatch plan generated', detail: `${plan.plans.length} feasible allocations · ${plan.residuals.reduce((sum, r) => sum + r.quantity, 0)} residual quantity`, tone: 'blue', time: timestamp }, ...current.activity], lastUpdated: timestamp }
    })
    setPage('dispatch')
    notify(generated?.plans.length ? `${generated.plans.length} feasible allocations generated. Hard constraints applied first.` : 'No feasible allocations found. Review the rejection reasons in Dispatch center.', generated?.plans.length ? 'success' : 'error')
  }

  function approvePlan(planId) {
    let result
    setState((current) => {
      result = approveDispatchPlan(current, planId, new Date())
      if (!result.ok) return current
      const timestamp = new Date().toISOString()
      return { ...result.state, audits: [{ id: `AUD-${Date.now()}`, actor: 'operator.demo', entity: result.shipment.id, from: 'PROPOSED', to: 'RESERVED', reason: current.plans.find((plan) => plan.id === planId)?.explanation || 'Feasible dispatch plan approved', result: 'PASS', time: timestamp }, ...current.audits], activity: [{ id: `ACT-${Date.now()}`, title: 'Reservation committed', detail: `${result.shipment.id} · ${result.shipment.quantity} ${result.shipment.unit}`, tone: 'blue', time: timestamp }, ...current.activity], lastUpdated: timestamp }
    })
    if (!result?.ok) { notify(result?.errors?.join(' · ') || 'The dispatch plan could not be approved.', 'error'); return }
    setSelectedShipment(result.shipment.id); notify(`Reservation created for ${result.shipment.quantity} ${result.shipment.unit}.`)
  }

  function changeShipment(shipmentId, nextStatus) {
    const shipment = state.shipments.find((s) => s.id === shipmentId)
    if (!shipment) return
    try {
      const next = transitionShipment(shipment, nextStatus)
      const approvedReroute = shipment.status === 'REROUTE_PENDING' && nextStatus === 'IN_TRANSIT' && shipment.proposedShelterId
      update((current) => ({ ...current, shelters: approvedReroute ? current.shelters.map((s) => s.id === shipment.proposedShelterId ? { ...s, remainingDemand: Math.max(0, s.remainingDemand - shipment.quantity), activeInbound: s.activeInbound + shipment.quantity } : s) : current.shelters, shipments: current.shipments.map((s) => s.id === shipmentId ? { ...next, shelterId: approvedReroute ? shipment.proposedShelterId : s.shelterId, proposedShelterId: undefined, timeline: [{ label: approvedReroute ? 'Reroute approved' : nextStatus.replaceAll('_', ' '), time: new Date().toISOString(), detail: approvedReroute ? `Custody transferred to validated fallback destination` : `State transitioned by ${role}` }, ...(s.timeline || [])] } : s), audits: [{ id: `AUD-${Date.now()}`, actor: role, entity: shipmentId, from: shipment.status, to: nextStatus, reason: approvedReroute ? `Reroute approved to ${shipment.proposedShelterId}; custody preserved` : `Operator action from shipment workspace`, result: 'PASS', time: new Date().toISOString() }, ...current.audits], activity: [{ id: `ACT-${Date.now()}`, title: approvedReroute ? 'Shipment rerouted safely' : `Shipment ${nextStatus.toLowerCase().replaceAll('_', ' ')}`, detail: `${shipmentId} · ${shipment.quantity} ${shipment.unit}`, tone: approvedReroute || nextStatus === 'DELIVERED' ? 'green' : 'blue', time: new Date().toISOString() }, ...current.activity] }))
      notify(`${shipmentId} moved to ${nextStatus.replaceAll('_', ' ')}.`)
    } catch (error) { notify(error.message, 'error') }
  }

  function closeShelter(shelterId) {
    let result
    setState((current) => {
      result = closeShelterAndRevalidate(current, shelterId, new Date())
      if (!result.ok) return current
      const shelter = current.shelters.find((item) => item.id === shelterId)
      const fallback = result.proposals.find((proposal) => proposal.fallback)?.fallback
      const timestamp = new Date().toISOString()
      return { ...result.state, exceptions: [{ id: `EX-${Date.now()}`, severity: fallback ? 'HIGH' : 'CRITICAL', type: 'Destination change', entity: shelterId, title: fallback ? `${shelter.name} closed during transit` : 'No safe fallback destination', detail: fallback ? `Affected shipment(s) require approval before handoff to ${fallback.name}.` : 'Affected custody is preserved. Operator intervention is required.', action: fallback ? 'Review reroute' : 'Escalate recovery', status: 'OPEN', createdAt: timestamp }, ...current.exceptions], audits: [{ id: `AUD-${Date.now()}`, actor: 'operator.demo', entity: shelterId, from: 'OPEN', to: 'CLOSED', reason: 'Destination closed; impacted shipments revalidated', result: fallback ? 'REROUTE_PENDING' : 'RECOVERY_REQUIRED', time: timestamp }, ...current.audits], activity: [{ id: `ACT-${Date.now()}`, title: 'Destination change detected', detail: fallback ? 'Shipment(s) need reroute approval' : 'No safe fallback found; recovery required', tone: fallback ? 'amber' : 'red', time: timestamp }, ...current.activity], lastUpdated: timestamp }
    })
    if (!result?.ok) { notify(result?.errors?.join(' · ') || 'Shelter closure could not be applied.', 'error'); return }
    const fallback = result.proposals.find((proposal) => proposal.fallback)?.fallback
    notify(fallback ? 'Shelter closed. A safe reroute proposal is ready for review.' : 'Shelter closed. Shipment custody preserved; recovery required.', fallback ? 'success' : 'error')
  }

  function runScenario(scenarioId) {
    const scenario = SCENARIOS.find((item) => item.id === scenarioId)
    if (!scenario) return
    const now = new Date().toISOString()
    const result = executeScenario(state, scenarioId, new Date())
    update((current) => ({ ...result.state, scenarioRuns: [{ scenarioId, scenarioTitle: scenario.title, outcome: 'PASS', summary: result.summary, checks: result.checks, time: now }, ...current.scenarioRuns], activity: [{ id: `ACT-${Date.now()}`, title: `Scenario ${scenario.letter} completed`, detail: result.summary, tone: 'green', time: now }, ...current.activity], audits: [{ id: `AUD-${Date.now()}`, actor: 'simulation.lab', entity: `SCN-${scenario.letter}`, from: 'READY', to: 'COMPLETED', reason: result.summary, result: 'PASS', time: now }, ...current.audits], lastUpdated: now }))
    notify(`Scenario ${scenario.letter} passed. Shared business rules and evidence recorded.`)
  }

  function createDonation(event) {
    event.preventDefault()
    const form = new FormData(event.currentTarget)
    const quantity = Number(form.get('quantity'))
    const itemType = form.get('itemType')
    if (!quantity || quantity < 1) { notify('Enter a positive donation quantity.', 'error'); return }
    const donation = { id: `BAT-${String(Date.now()).slice(-4)}`, donor: form.get('donor') || 'Demo donor', itemType, quantity, availableQuantity: quantity, completedQuantity: 0, unit: form.get('unit') || 'units', pickupLocation: form.get('pickupLocation'), pickupDeadline: form.get('pickupDeadline'), declaredExpiry: form.get('declaredExpiry'), safeDeadline: form.get('safeDeadline'), dependencies: form.get('dependencies') ? form.get('dependencies').split(',').map((value) => value.trim()).filter(Boolean) : [], handling: form.get('handling') || 'Standard handling', status: 'READY', createdAt: new Date().toISOString() }
    update((current) => ({ ...current, donations: [donation, ...current.donations], activity: [{ id: `ACT-${Date.now()}`, title: 'Donation created', detail: `${donation.id} · ${quantity} ${donation.unit} awaiting allocation`, tone: 'green', time: new Date().toISOString() }, ...current.activity], audits: [{ id: `AUD-${Date.now()}`, actor: role, entity: donation.id, from: 'NEW', to: 'READY', reason: 'Donation passed required field validation', result: 'PASS', time: new Date().toISOString() }, ...current.audits] }))
    event.currentTarget.reset(); setPage('donations'); notify(`${donation.id} created and added to eligible inventory.`)
  }

  return <div className="app-shell">
    <aside className="sidebar">
      <div className="brand"><div className="brand-mark">RQ</div><div><strong>ResQRoute</strong><span>Operations command center</span></div></div>
      <div className="environment"><span className="status-dot"></span><span>DEMO SIMULATION</span><small>Local state · deterministic</small></div>
      <nav className="nav-list">{NAV.map(([id, label, icon]) => <button key={id} className={`nav-item ${page === id ? 'active' : ''}`} onClick={() => setPage(id)}><Icon name={icon} /><span>{label}</span>{id === 'exceptions' && metrics.exceptions > 0 && <em>{metrics.exceptions}</em>}</button>)}</nav>
      <div className="sidebar-footer"><button className="nav-item" onClick={() => setPage('settings')}><Icon name="settings" /><span>Settings</span></button><div className="mini-profile"><div className="avatar">OP</div><div><strong>Demo operator</strong><span>Operations admin</span></div><Icon name="chevron" size={14} /></div></div>
    </aside>
    <main className="main-shell">
      <header className="topbar"><div className="breadcrumbs"><span>ResQRoute</span><Icon name="chevron" size={14} /><strong>{NAV.find(([id]) => id === page)?.[1] || 'Settings'}</strong></div><div className="top-actions"><label className="search"><Icon name="search" size={16} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search shipments, IDs, shelters..." /></label><div className="network"><span className="status-dot"></span>Network healthy</div><button className="icon-button" aria-label="Notifications"><Icon name="bell" size={18} /><i></i></button><select className="role-select" value={role} onChange={(event) => setRole(event.target.value)}><option>Operations administrator</option><option>Volunteer rider</option><option>Shelter operator</option><option>Donor</option></select><div className="avatar avatar-large">OP</div></div></header>
      <div className="page-content">{page === 'overview' && <Dashboard metrics={metrics} state={state} selected={selected} setSelectedShipment={setSelectedShipment} setPage={setPage} generatePlan={generatePlan} />}{page === 'donations' && <Donations state={state} query={query} setPage={setPage} setModal={setModal} />}{page === 'shelters' && <Shelters state={state} closeShelter={closeShelter} />}{page === 'riders' && <Riders state={state} />}{page === 'dispatch' && <Dispatch state={state} generatePlan={generatePlan} approvePlan={approvePlan} />}{page === 'shipments' && <Shipments state={state} selected={selected} setSelectedShipment={setSelectedShipment} changeShipment={changeShipment} expireReservation={expireSelectedReservation} />}{page === 'exceptions' && <Exceptions state={state} generatePlan={generatePlan} setPage={setPage} />}{page === 'simulation' && <Simulation state={state} runScenario={runScenario} reset={reset} />}{page === 'audit' && <Audit state={state} />}{page === 'settings' && <Settings reset={reset} />}</div>
    </main>
    {toast && <div className={`toast toast-${toast.tone}`}><span className="toast-icon"><Icon name={toast.tone === 'error' ? 'alert' : 'check'} size={15} /></span>{toast.message}<button onClick={() => setToast(null)}><Icon name="close" size={14} /></button></div>}
    {modal === 'create-donation' && <Modal title="Create donation batch" onClose={() => setModal(null)}><DonationForm createDonation={createDonation} /></Modal>}
  </div>
}

function Dashboard({ metrics, state, selected, setSelectedShipment, setPage, generatePlan }) {
  return <>
    <div className="page-intro"><div><div className="eyebrow">Friday · October 23, 2026 · 09:42 local</div><h1>Good morning, operator.</h1><p>Live coordination across donors, riders, and receiving centers.</p></div><div className="intro-actions"><Badge tone="teal">Simulated clock · +00:00</Badge><Button icon="route" onClick={generatePlan}>Generate dispatch plan</Button></div></div>
    <div className="metric-grid">{[[metrics.activeBatches, 'Active donation batches', 'Awaiting allocation', 'box', 'teal', 'donations'], [metrics.inTransit, 'Shipments in transit', 'Live custody', 'truck', 'blue', 'shipments'], [metrics.riders, 'Available riders', 'Heartbeat healthy', 'users', 'green', 'riders'], [metrics.exceptions, 'Open exceptions', 'Needs review', 'alert', 'amber', 'exceptions']].map(([value, label, sub, icon, tone, target]) => <button className="metric-card" key={label} onClick={() => setPage(target)}><div className={`metric-icon ${tone}`}><Icon name={icon} /></div><div className="metric-copy"><strong>{value}</strong><span>{label}</span><small>{sub}</small></div><Icon name="chevron" size={15} /></button>)}</div>
    <div className="secondary-metrics"><Metric label="Meals safely delivered" value={metrics.deliveredMeals} unit="meals" tone="green" /><Metric label="Aid units delivered" value={metrics.deliveredAid} unit="units" tone="teal" /><Metric label="Awaiting allocation" value={metrics.awaiting} unit="units" tone="amber" /><Metric label="Reservations recovered" value={metrics.recovered} unit="events" tone="blue" /><Metric label="Successful reroutes" value={metrics.reroutes} unit="events" tone="purple" /></div>
    <div className="dashboard-grid"><div className="panel map-panel"><SectionHeading eyebrow="Network schematic" title="Live logistics map" detail="Seeded locations · route ETAs are estimates" action={<Badge tone="blue">{state.shipments.filter((s) => s.status === 'IN_TRANSIT').length} active routes</Badge>} /><SchematicMap shipments={state.shipments} shelters={state.shelters} selectedId={selected?.id} onSelect={setSelectedShipment} /></div><div className="panel exceptions-panel"><SectionHeading eyebrow="Action queue" title="Priority exceptions" detail="Ranked by safety and operational impact" action={<Button variant="quiet" onClick={() => setPage('exceptions')}>View all <Icon name="chevron" size={14} /></Button>} /><div className="exception-list">{state.exceptions.filter((e) => e.status === 'OPEN').slice(0, 4).map((exception) => <ExceptionRow key={exception.id} exception={exception} />)}</div></div></div>
    <div className="dashboard-bottom"><div className="panel activity-panel"><SectionHeading eyebrow="Event stream" title="Recent activity" action={<Button variant="quiet" onClick={() => setPage('audit')}>Open audit <Icon name="chevron" size={14} /></Button>} /><div className="activity-list">{state.activity.slice(0, 5).map((item) => <div className="activity-row" key={item.id}><span className={`activity-dot ${item.tone}`}></span><div><strong>{item.title}</strong><span>{item.detail}</span></div><time>{fmtTime(item.time)}</time></div>)}</div></div><ShipmentDetail shipment={selected} state={state} setPage={setPage} /></div>
  </>
}

function Metric({ label, value, unit, tone }) { return <div className="secondary-metric"><span className={`metric-line ${tone}`}></span><div><strong>{value}</strong><span>{unit}</span></div><small>{label}</small></div> }

function SchematicMap({ shipments, shelters, selectedId, onSelect }) {
  const points = { 'S-01': [76, 28], 'S-02': [85, 66], 'S-03': [52, 73], 'S-04': [25, 57], 'S-05': [18, 22] }
  return <div className="schematic"><div className="map-label top-left">NORTH DISTRICT</div><div className="map-label bottom-right">SIMULATED GEOMETRY · NOT LIVE TRAFFIC</div><div className="road road-one"></div><div className="road road-two"></div><div className="road road-three"></div><div className="map-route route-one"></div><div className="map-route route-two"></div>{shelters.map((shelter) => <button key={shelter.id} className={`map-point shelter-point ${shelter.status === 'CLOSED' ? 'closed' : ''}`} style={{ left: `${points[shelter.id][0]}%`, top: `${points[shelter.id][1]}%` }} onClick={() => onSelect(shipments.find((s) => s.shelterId === shelter.id)?.id || selectedId)}><span className="point-core"><Icon name="home" size={14} /></span><span>{shelter.name}</span></button>)}<button className="map-point donor-point" style={{ left: '35%', top: '28%' }}><span className="point-core"><Icon name="box" size={14} /></span><span>Northside Kitchen</span></button><button className="map-point rider-point" style={{ left: '53%', top: '43%' }}><span className="point-core"><Icon name="truck" size={14} /></span><span>R-07 · in transit</span></button><div className="map-legend"><span><i className="legend-dot blue"></i> In transit</span><span><i className="legend-dot green"></i> Available</span><span><i className="legend-dot amber"></i> At risk</span></div></div>
}

function ExceptionRow({ exception }) { return <div className="exception-row"><div className={`severity ${exception.severity.toLowerCase()}`}>{exception.severity === 'CRITICAL' ? '!' : exception.severity === 'HIGH' ? '↑' : '·'}</div><div className="exception-copy"><div><Badge tone={exception.severity === 'CRITICAL' ? 'red' : exception.severity === 'HIGH' ? 'amber' : 'slate'}>{exception.type}</Badge><time>{fmtTime(exception.createdAt)}</time></div><strong>{exception.title}</strong><span>{exception.detail}</span><button>{exception.action} <Icon name="chevron" size={12} /></button></div></div> }

function ShipmentDetail({ shipment, state, setPage }) { if (!shipment) return <div className="panel detail-panel"><EmptyState title="No shipment selected" detail="Select a route from the schematic to inspect state." /></div>; const rider = state.riders.find((r) => r.id === shipment.riderId); const shelter = state.shelters.find((s) => s.id === shipment.shelterId); return <div className="panel detail-panel"><div className="detail-header"><div><div className="eyebrow">Selected shipment</div><h3>{shipment.id}</h3></div><Badge tone={shipment.status === 'DELIVERED' ? 'green' : shipment.status === 'IN_TRANSIT' ? 'blue' : shipment.status === 'RECOVERY_REQUIRED' ? 'red' : 'amber'}>{shipment.status.replaceAll('_', ' ')}</Badge></div><div className="shipment-summary"><div><span>Load</span><strong>{shipment.quantity} {shipment.unit}</strong></div><div><span>Rider</span><strong>{rider?.name || shipment.riderId}</strong></div><div><span>Destination</span><strong>{shelter?.name || shipment.shelterId}</strong></div></div><div className="deadline-block"><div><span>Validated safe-use deadline</span><strong>{fmtDate(shipment.safeDeadline)} · {fmtTime(shipment.safeDeadline)}</strong></div><b>{minutesLeft(shipment.safeDeadline)}m <small>remaining</small></b></div><div className="mini-timeline">{(shipment.timeline || []).slice(0, 3).map((event, index) => <div key={`${event.label}-${index}`}><span className={index === 0 ? 'current' : ''}></span><div><strong>{event.label}</strong><small>{event.detail}</small></div><time>{fmtTime(event.time)}</time></div>)}</div><Button variant="quiet" onClick={() => setPage('shipments')}>Open full shipment record <Icon name="chevron" size={14} /></Button></div> }

function Donations({ state, query, setPage, setModal }) { const rows = state.donations.filter((d) => `${d.id} ${d.donor} ${d.itemType}`.toLowerCase().includes(query.toLowerCase())); return <><SectionHeading eyebrow="Inventory control" title="Donations" detail="Every batch keeps a separate declared expiry and validated safe-use deadline." action={<Button icon="plus" onClick={() => setModal('create-donation')}>Create donation</Button>} /><div className="filterbar"><label className="search table-search"><Icon name="search" size={16} /><input value={query} readOnly placeholder="Search current batch view..." /></label><select><option>All statuses</option><option>Ready</option><option>Partially allocated</option><option>Delivered</option></select><Button variant="quiet" icon="download">Export CSV</Button></div><div className="panel table-panel"><table><thead><tr><th>Batch</th><th>Donor / item</th><th>Quantity</th><th>Pickup deadline</th><th>Safe-use deadline</th><th>Status</th><th></th></tr></thead><tbody>{rows.map((donation) => <tr key={donation.id}><td><strong className="mono">{donation.id}</strong><small>{fmtDate(donation.createdAt)} · {donation.pickupLocation}</small></td><td><strong>{donation.donor}</strong><small>{donation.itemType} · {donation.handling}</small></td><td><strong>{donation.availableQuantity}</strong><small>of {donation.quantity} {donation.unit} available</small></td><td><strong>{fmtTime(donation.pickupDeadline)}</strong><small>{minutesLeft(donation.pickupDeadline)}m left</small></td><td><strong>{fmtTime(donation.safeDeadline)}</strong><small>{minutesLeft(donation.safeDeadline)}m remaining</small></td><td><Badge tone={donation.status === 'DELIVERED' ? 'green' : donation.availableQuantity > 0 ? 'amber' : 'slate'}>{donation.status.replaceAll('_', ' ')}</Badge></td><td><button className="row-action" onClick={() => setPage('dispatch')}>Inspect <Icon name="chevron" size={13} /></button></td></tr>)}</tbody></table>{rows.length === 0 && <EmptyState title="No matching donations" detail="Try a different search term." />}</div></> }

function Shelters({ state, closeShelter }) { return <><SectionHeading eyebrow="Receiving network" title="Shelters" detail="Demand, capacity, intake state, and resource readiness." /><div className="card-grid shelter-grid">{state.shelters.map((shelter) => <div className="panel entity-card" key={shelter.id}><div className="entity-card-head"><div><span className="overline">{shelter.id}</span><h3>{shelter.name}</h3><p>{shelter.location}</p></div><Badge tone={shelter.status === 'OPEN' ? 'green' : 'red'}>{shelter.status}</Badge></div><div className="progress-label"><span>Remaining demand</span><strong>{shelter.remainingDemand}</strong></div><div className="progress"><span style={{ width: `${Math.min(100, (shelter.remainingDemand / Math.max(shelter.intakeCapacity || 1, shelter.remainingDemand)) * 100)}%` }}></span></div><div className="entity-stats"><div><small>Intake capacity</small><strong>{shelter.intakeCapacity}</strong></div><div><small>Inbound</small><strong>{shelter.activeInbound}</strong></div><div><small>Resources</small><strong>{shelter.resources.length}</strong></div></div><div className="chip-row">{shelter.resources.map((resource) => <span className="chip" key={resource}>{resource}</span>)}</div><div className="entity-card-actions">{shelter.status === 'OPEN' ? <Button variant="danger" onClick={() => closeShelter(shelter.id)}>Close intake</Button> : <Button variant="quiet">Review closure</Button>}<button className="row-action">View demand <Icon name="chevron" size={13} /></button></div></div>)}</div></> }

function Riders({ state }) { return <><SectionHeading eyebrow="Volunteer network" title="Riders" detail="Availability and custody capacity are checked before any reservation." action={<Button icon="plus">Add rider</Button>} /><div className="panel table-panel"><table><thead><tr><th>Rider</th><th>Availability</th><th>Capacity</th><th>Supported items</th><th>Heartbeat</th><th>Reliability</th><th></th></tr></thead><tbody>{state.riders.map((rider) => <tr key={rider.id}><td><div className="person-cell"><div className="avatar avatar-small">{rider.name.split(' ').map((n) => n[0]).join('')}</div><div><strong>{rider.name}</strong><small className="mono">{rider.id} · {rider.location}</small></div></div></td><td><Badge tone={rider.availability === 'AVAILABLE' ? 'green' : 'red'}>{rider.availability}</Badge></td><td><strong>{rider.activeLoad} / {rider.maxCapacity}</strong><small>active load / max</small></td><td><div className="chip-row compact">{rider.supported.slice(0, 2).map((item) => <span className="chip" key={item}>{item}</span>)}</div></td><td><strong>{fmtTime(rider.heartbeat)}</strong><small>{Math.max(0, Math.round((Date.now() - new Date(rider.heartbeat).getTime()) / 60000))}m ago</small></td><td><div className="reliability"><span style={{ width: `${rider.reliability * 100}%` }}></span></div><small>{Math.round(rider.reliability * 100)}% reliability</small></td><td><button className="row-action">Inspect <Icon name="chevron" size={13} /></button></td></tr>)}</tbody></table></div></> }

function Dispatch({ state, generatePlan, approvePlan }) { const plans = state.plans || []; const residuals = state.residuals || []; const rejections = state.rejections || []; const invariant = assertNetworkInvariants(state); return <><SectionHeading eyebrow="Explainable allocation" title="Dispatch center" detail="Hard constraints first. Ranking only compares safe, feasible options." action={<Button icon="refresh" onClick={generatePlan}>Refresh plan</Button>} /><div className="dispatch-banner"><div className="dispatch-badge"><Icon name="route" size={20} /></div><div><strong>{plans.filter((p) => p.status === 'PROPOSED').length || 'No'} feasible recommendations ready</strong><span>Every recommendation below passed deadline, capacity, demand, compatibility, and dependency checks.</span></div><div className="score-legend"><span><i className="legend-dot green"></i> Feasible</span><span><i className="legend-dot red"></i> Blocked before ranking</span></div></div>{plans.length === 0 ? <div className="panel dispatch-empty"><EmptyState title="No active plan" detail="Generate a plan to evaluate eligible inventory against the current rider and shelter network." /><Button icon="route" onClick={generatePlan}>Generate first plan</Button>{rejections.length > 0 && <div className="rejection-summary"><strong>Rejected combinations</strong>{rejections.slice(0, 5).map((rejection, index) => <span key={`${rejection.donationId}-${rejection.shelterId}-${rejection.riderId}-${index}`}><span className="mono">{rejection.donationId} · {rejection.riderId} · {rejection.shelterId}</span> — {rejection.reasons.join(' · ')}</span>)}</div>}</div> : <div className="dispatch-layout"><div className="panel table-panel"><div className="panel-title"><div><span className="eyebrow">Plan recommendations</span><h3>Feasible allocations</h3></div><Badge tone="teal">{plans.length} candidates</Badge></div><table><thead><tr><th>Donation</th><th>Assignment</th><th>Quantity</th><th>Score</th><th>Decision</th></tr></thead><tbody>{plans.map((plan) => { const donation = state.donations.find((d) => d.id === plan.donationId); const rider = state.riders.find((r) => r.id === plan.riderId); const shelter = state.shelters.find((s) => s.id === plan.shelterId); return <tr key={plan.id}><td><strong className="mono">{plan.donationId}</strong><small>{donation?.itemType}</small></td><td><strong>{rider?.name}</strong><small>→ {shelter?.name}</small></td><td><strong>{plan.quantity}</strong><small>{donation?.unit}</small></td><td><strong className="score">{Math.round(plan.score * 100)}</strong><div className="score-bar"><span style={{ width: `${plan.score * 100}%` }}></span></div></td><td>{plan.status === 'PROPOSED' ? <Button variant="small" onClick={() => approvePlan(plan.id)}>Approve</Button> : <Badge tone="green">Approved</Badge>}</td></tr>})}</tbody></table></div><div className="panel rationale-panel"><div className="panel-title"><div><span className="eyebrow">Decision trace</span><h3>Why this plan</h3></div><Icon name="pulse" size={20} /></div>{plans.slice(0, 2).map((plan) => <div className="rationale" key={plan.id}><div className="rationale-head"><strong>{plan.donationId} → {plan.shelterId}</strong><Badge tone="teal">{Math.round(plan.score * 100)} / 100</Badge></div><p>{plan.explanation}</p><div className="factor-list">{Object.entries(plan.factors || {}).map(([key, value]) => <div key={key}><span>{key}</span><strong>{Math.round(value * 100)}</strong><i><em style={{ width: `${value * 100}%` }}></em></i></div>)}</div></div>)}{residuals.length > 0 && <div className="residual-box"><strong>{residuals.reduce((sum, item) => sum + item.quantity, 0)} units remain unallocated</strong><span>{residuals.flatMap((r) => r.reasons).length ? residuals.flatMap((r) => r.reasons).slice(0, 2).join(' · ') : 'All currently eligible rider and shelter capacity was used.'}</span></div>}<div className={`invariant-box ${invariant.valid ? 'valid' : 'invalid'}`}><strong>Network quantity invariants</strong><span>{invariant.valid ? 'Valid · quantities, capacities, and demand reconcile.' : invariant.errors.join(' · ')}</span></div></div></div>}</> }

function Shipments({ state, selected, setSelectedShipment, changeShipment, expireReservation }) { return <><SectionHeading eyebrow="Custody tracking" title="Live shipments" detail="State transitions are validated and audited before they appear here." /><div className="shipments-layout"><div className="panel shipment-list-panel"><div className="panel-title"><div><span className="eyebrow">Current network</span><h3>{state.shipments.length} shipment records</h3></div><select><option>All statuses</option><option>In transit</option><option>Delivered</option></select></div>{state.shipments.map((shipment) => <button className={`shipment-list-row ${selected?.id === shipment.id ? 'selected' : ''}`} key={shipment.id} onClick={() => setSelectedShipment(shipment.id)}><div className={`shipment-state-dot ${shipment.status.toLowerCase()}`}></div><div><strong>{shipment.id}</strong><span>{shipment.quantity} {shipment.unit} · {state.shelters.find((s) => s.id === shipment.shelterId)?.name}</span></div><Badge tone={shipment.status === 'DELIVERED' ? 'green' : shipment.status === 'IN_TRANSIT' ? 'blue' : shipment.status === 'RECOVERY_REQUIRED' ? 'red' : 'amber'}>{shipment.status.replaceAll('_', ' ')}</Badge><Icon name="chevron" size={14} /></button>)}</div><ShipmentWorkspace shipment={selected} state={state} changeShipment={changeShipment} expireReservation={expireReservation} /></div></> }

function ShipmentWorkspace({ shipment, state, changeShipment, expireReservation }) { if (!shipment) return <div className="panel"><EmptyState title="Select a shipment" detail="Choose a shipment from the list to inspect its operational record." /></div>; const rider = state.riders.find((r) => r.id === shipment.riderId); const shelter = state.shelters.find((s) => s.id === shipment.shelterId); const next = { RESERVED: 'ACCEPTED', ACCEPTED: 'PICKED_UP', PICKED_UP: 'IN_TRANSIT', IN_TRANSIT: 'DELIVERED' }[shipment.status]; return <div className="panel workspace-panel"><div className="workspace-head"><div><div className="eyebrow">Shipment record</div><h2>{shipment.id}</h2><p>{shipment.itemType} · {shipment.quantity} {shipment.unit}</p></div><Badge tone={shipment.status === 'DELIVERED' ? 'green' : shipment.status === 'IN_TRANSIT' ? 'blue' : shipment.status === 'RECOVERY_REQUIRED' ? 'red' : 'amber'}>{shipment.status.replaceAll('_', ' ')}</Badge></div><div className="route-strip"><div><span className="route-node donor"></span><small>Origin</small><strong>{state.donations.find((d) => d.id === shipment.donationId)?.pickupLocation || 'Donor'}</strong></div><div className="route-line"><span>ETA {fmtTime(shipment.eta)}</span></div><div><span className="route-node shelter"></span><small>Destination</small><strong>{shelter?.name || shipment.shelterId}</strong></div></div><div className="workspace-grid"><div><span className="eyebrow">State timeline</span><div className="full-timeline">{['AVAILABLE', 'RESERVED', 'ACCEPTED', 'PICKED_UP', 'IN_TRANSIT', 'DELIVERED'].map((status) => { const active = ['AVAILABLE', 'RESERVED', 'ACCEPTED', 'PICKED_UP', 'IN_TRANSIT', 'DELIVERED'].indexOf(status) <= ['AVAILABLE', 'RESERVED', 'ACCEPTED', 'PICKED_UP', 'IN_TRANSIT', 'DELIVERED'].indexOf(shipment.status); return <div className={active ? 'done' : ''} key={status}><span>{active ? <Icon name="check" size={12} /> : ''}</span><strong>{status.replaceAll('_', ' ')}</strong></div> })}</div></div><div className="validation-card"><span className="eyebrow">Validation snapshot</span><div className="validation-row"><Icon name="check" size={15} /><span>Rider capacity</span><strong>{rider ? `${rider.activeLoad} / ${rider.maxCapacity}` : '—'}</strong></div><div className="validation-row"><Icon name="check" size={15} /><span>Destination demand</span><strong>{shelter?.remainingDemand ?? '—'} remaining</strong></div><div className="validation-row"><Icon name="check" size={15} /><span>Safe-use deadline</span><strong>{minutesLeft(shipment.safeDeadline)}m left</strong></div></div></div><div className="workspace-actions"><span className="eyebrow">Available actions</span><div>{next && <Button onClick={() => changeShipment(shipment.id, next)} icon="check">Confirm {next.replaceAll('_', ' ').toLowerCase()}</Button>}{shipment.status === 'RESERVED' && <Button variant="danger" onClick={() => expireReservation(shipment.id)}>Expire reservation</Button>}{shipment.status === 'IN_TRANSIT' && <Button variant="danger" onClick={() => changeShipment(shipment.id, 'REROUTE_PENDING')}>Report issue</Button>}{shipment.status === 'REROUTE_PENDING' && <Button variant="quiet" onClick={() => changeShipment(shipment.id, 'IN_TRANSIT')}>Approve safe reroute</Button>}</div></div></div> }

function Exceptions({ state, generatePlan, setPage }) { return <><SectionHeading eyebrow="Control tower" title="Exception center" detail="Actionable issues with safe, state-aware next steps." action={<Button icon="refresh" onClick={generatePlan}>Revalidate network</Button>} /><div className="exception-summary"><Metric label="Critical" value={state.exceptions.filter((e) => e.severity === 'CRITICAL').length} unit="open" tone="red" /><Metric label="High priority" value={state.exceptions.filter((e) => e.severity === 'HIGH').length} unit="open" tone="amber" /><Metric label="Awaiting action" value={state.exceptions.filter((e) => e.status === 'OPEN').length} unit="items" tone="blue" /></div><div className="panel exception-center">{state.exceptions.map((exception) => <div className="exception-detail" key={exception.id}><div className={`severity large ${exception.severity.toLowerCase()}`}>{exception.severity === 'CRITICAL' ? '!' : exception.severity === 'HIGH' ? '↑' : '·'}</div><div className="exception-detail-copy"><div className="exception-meta"><Badge tone={exception.severity === 'CRITICAL' ? 'red' : exception.severity === 'HIGH' ? 'amber' : 'slate'}>{exception.severity}</Badge><span>{exception.type}</span><span className="mono">{exception.entity}</span><time>{fmtDate(exception.createdAt)} · {fmtTime(exception.createdAt)}</time></div><h3>{exception.title}</h3><p>{exception.detail}</p><div className="exception-actions"><Button variant="quiet" onClick={() => setPage(exception.entity.startsWith('SHP') ? 'shipments' : exception.entity.startsWith('BAT') ? 'dispatch' : 'shelters')}>Inspect affected state</Button><Button variant="small" onClick={generatePlan}>Revalidate</Button></div></div><Badge tone={exception.status === 'OPEN' ? 'amber' : 'green'}>{exception.status}</Badge></div>)}</div></> }

function Simulation({ state, runScenario, reset }) { const last = state.scenarioRuns?.[0]; return <><SectionHeading eyebrow="Judge readiness" title="Simulation lab" detail="Deterministic failure scenarios reuse the same allocation and recovery rules." action={<Button variant="danger" icon="refresh" onClick={reset}>Reset demo baseline</Button>} /><div className="simulation-banner"><div className="simulation-clock"><span className="eyebrow">Simulated clock</span><strong>+00:00:00</strong><small>Manual mode · local deterministic state</small></div><div><strong>Run the operational proof, not a static walkthrough.</strong><span>Each scenario records actual state changes, checks, and an audit event so judges can inspect the result.</span></div><Badge tone="teal">8 scenarios ready</Badge></div><div className="scenario-grid">{SCENARIOS.map((scenario) => <div className="panel scenario-card" key={scenario.id}><div className="scenario-letter">{scenario.letter}</div><div className="scenario-content"><div className="scenario-head"><div><span className="overline">Scenario {scenario.letter}</span><h3>{scenario.title}</h3></div>{last?.scenarioId === scenario.id && <Badge tone="green">Passed</Badge>}</div><p>{scenario.detail}</p><div className="scenario-expected"><span>Expected outcome</span><strong>{scenario.expected}</strong></div><Button icon="play" onClick={() => runScenario(scenario.id)}>Run scenario</Button></div></div>)}</div>{last && <div className="panel run-result"><div><span className="eyebrow">Latest run</span><h3>Scenario {SCENARIOS.find((s) => s.id === last.scenarioId)?.letter} · {last.scenarioTitle}</h3><p>{last.summary}</p></div><div className="result-checks">{last.checks.map((check) => <span key={check}><Icon name="check" size={14} />{check}</span>)}</div><Badge tone="green">{last.outcome}</Badge></div>}<div className="panel event-inspector"><SectionHeading eyebrow="State inspector" title="Latest simulation evidence" detail="Seeded locations, ETAs, and outcomes are clearly labelled." /><div className="inspector-grid"><div><span>Active entities</span><strong>{state.donations.length + state.shelters.length + state.riders.length + state.shipments.length}</strong></div><div><span>Audit events</span><strong>{state.audits.length}</strong></div><div><span>Open exceptions</span><strong>{state.exceptions.filter((e) => e.status === 'OPEN').length}</strong></div><div><span>Quantity awaiting allocation</span><strong>{state.donations.reduce((sum, d) => sum + d.availableQuantity, 0)}</strong></div></div></div></> }

function Audit({ state }) { return <><SectionHeading eyebrow="Traceability" title="Audit & impact" detail="Confirmed shipment events only. Simulation records are labelled and reproducible." action={<Button variant="quiet" icon="download">Export audit CSV</Button>} /><div className="impact-grid"><div className="impact-hero"><span className="eyebrow">Confirmed impact</span><strong>{state.shipments.filter((s) => s.status === 'DELIVERED').reduce((sum, s) => sum + s.quantity, 0)}</strong><span>aid units delivered</span><small>Based on committed delivery confirmations</small></div><Metric label="Meals delivered" value={state.shipments.filter((s) => s.status === 'DELIVERED' && s.itemType === 'Prepared meals').reduce((sum, s) => sum + s.quantity, 0)} unit="meals" tone="green" /><Metric label="Reroutes recorded" value={state.audits.filter((a) => /reroute/i.test(a.reason)).length} unit="events" tone="blue" /><Metric label="Blocked before dispatch" value={state.exceptions.filter((e) => /deadline|dependency/i.test(e.type)).length} unit="events" tone="red" /></div><div className="panel table-panel"><div className="panel-title"><div><span className="eyebrow">Immutable event log</span><h3>Audit trail</h3></div><Badge tone="slate">{state.audits.length} events</Badge></div><table><thead><tr><th>Actor</th><th>Entity</th><th>Transition</th><th>Reason</th><th>Result</th><th>Time</th></tr></thead><tbody>{state.audits.map((audit) => <tr key={audit.id}><td><strong>{audit.actor}</strong><small className="mono">{audit.id}</small></td><td><strong className="mono">{audit.entity}</strong></td><td><span className="transition">{audit.from}</span><Icon name="chevron" size={12} /><span className="transition">{audit.to}</span></td><td><span className="reason">{audit.reason}</span></td><td><Badge tone={audit.result === 'PASS' ? 'green' : 'amber'}>{audit.result}</Badge></td><td><strong>{fmtDate(audit.time)}</strong><small>{fmtTime(audit.time)}</small></td></tr>)}</tbody></table></div></> }

function Settings({ reset }) { return <><SectionHeading eyebrow="Workspace controls" title="Settings" detail="Demo environment and product guardrails." /><div className="settings-grid"><div className="panel settings-card"><div className="setting-icon"><Icon name="flask" /></div><h3>Demo simulation mode</h3><p>Seeded local data is persisted in this browser so judges can rehearse the same operational states without external services.</p><div className="setting-row"><span>Persistence</span><Badge tone="green">Local browser state</Badge></div><div className="setting-row"><span>Routing provider</span><Badge tone="slate">Seeded estimates</Badge></div><div className="setting-row"><span>Clock</span><Badge tone="teal">Injectable demo clock</Badge></div></div><div className="panel settings-card"><div className="setting-icon"><Icon name="pulse" /></div><h3>Safety guardrails</h3><p>Hard constraints are evaluated before score ranking. The UI never claims success before the underlying state mutation completes.</p><div className="guardrail-list"><span><Icon name="check" size={14} />Deadline feasibility</span><span><Icon name="check" size={14} />Capacity and demand</span><span><Icon name="check" size={14} />Dependency compatibility</span><span><Icon name="check" size={14} />Idempotent transitions</span></div></div><div className="panel settings-card danger-card"><div className="setting-icon"><Icon name="refresh" /></div><h3>Reset workspace</h3><p>Restore the deterministic demo baseline, clear scenario runs, and return all seeded entities to their original state.</p><Button variant="danger" onClick={reset}>Reset demo baseline</Button></div></div></> }

function Modal({ title, onClose, children }) { return <div className="modal-backdrop" onClick={onClose}><div className="modal" onClick={(event) => event.stopPropagation()}><div className="modal-head"><div><span className="eyebrow">Inventory control</span><h2>{title}</h2></div><button className="icon-button" onClick={onClose}><Icon name="close" /></button></div>{children}</div></div> }
function DonationForm({ createDonation }) { const defaults = { pickup: new Date(Date.now() + 90 * 60000).toISOString().slice(0, 16), expiry: new Date(Date.now() + 180 * 60000).toISOString().slice(0, 16), safe: new Date(Date.now() + 150 * 60000).toISOString().slice(0, 16) }; return <form className="donation-form" onSubmit={createDonation}><div className="form-grid"><label>Donor name<input name="donor" defaultValue="Community partner" required /></label><label>Item type<select name="itemType" defaultValue="Prepared meals"><option>Prepared meals</option><option>Produce boxes</option><option>First aid kits</option><option>Water crates</option><option>Bread loaves</option><option>Ration kits</option></select></label><label>Quantity<input name="quantity" type="number" min="1" defaultValue="40" required /></label><label>Unit<input name="unit" defaultValue="meals" required /></label><label className="span-2">Pickup location<input name="pickupLocation" defaultValue="Demo partner · Main St" required /></label><label>Pickup deadline<input name="pickupDeadline" type="datetime-local" defaultValue={defaults.pickup} required /></label><label>Donor-declared expiry<input name="declaredExpiry" type="datetime-local" defaultValue={defaults.expiry} required /><small>Declared by donor; not a safety guarantee.</small></label><label>Validated safe-use deadline<input name="safeDeadline" type="datetime-local" defaultValue={defaults.safe} required /><small>Use a qualified validation source for regulated handling.</small></label><label>Handling requirements<input name="handling" defaultValue="Chilled · sealed" /></label><label className="span-2">Resource dependencies<input name="dependencies" placeholder="e.g. Refrigeration, Water" /><small>Comma-separated resources required at the receiving center.</small></label></div><div className="form-footer"><span><Icon name="alert" size={14} /> Unsafe or missing deadline information blocks dispatch.</span><Button type="submit" icon="check">Save donation batch</Button></div></form> }
